        "<strong>Vayyiqra (<em>וַיִּקְרָא</em>) — “and he called.”</strong> The Hebrew name of the book comes from this opening word. God <em>calls</em> Moses (a relational verb) before <em>speaking</em> to him; rabbinic tradition (<em>Sifra</em>) draws a contrast with Numbers 22, where God only speaks to Balaam — calling implies invitation. The English title <em>Leviticus</em> follows the LXX <em>Leuitikon</em>, “the Levitical [book],” though Levites as a class are barely mentioned in the book.",
