        "Word",
        "Word",
        "<strong>Salt covenants in the ancient Near East.</strong> Salt was a near-universal symbol of inviolable agreement: it does not decay, it preserves, and a meal shared with salt was considered binding. Numbers 18:19 and 2 Chronicles 13:5 both use the phrase “covenant of salt” for unbreakable divine commitments. Arabic <em>milḥah</em> and the related notion of <em>‘aysh wa-milḥ</em> (“bread and salt”) preserve the same custom.",
