        "Hebrew",
        "<strong>Azazel (<em>עֲזָאזֵל</em>).</strong> One of the most disputed words in the entire Hebrew Bible. Four major readings: (1) a wilderness demon to whom the goat is dispatched (the reading favored by 1 Enoch 10 and most modern scholars); (2) a place name, “rugged cliff,” where the goat is led (rabbinic tradition); (3) a compound noun, <em>‘ez ozel</em>, “the goat that goes away” (whence Tyndale’s English coinage <em>scapegoat</em>, 1530); (4) a contraction of an older Canaanite divine name. The translation choice silently commits the reader to one of these.",
        "User paraphrase; references 1 Enoch, Tyndale",
