    (
        17,
        11,
        "",
        "the life of the flesh is in the blood",
        "word",
        "Hebrew",
        "Hebrew",
        "<strong>Nephesh ha-basar ba-dam (<em>נֶפֶשׁ</em> <em>הַבָּשָׂר</em> <em>בַּדָּם</em>).</strong> The verse equates <em>nephesh</em> (often “soul,” here closer to “life-force”) with blood. From this emerges the universal Israelite blood-prohibition: blood belongs to God because life belongs to God. The rationale shows that Israelite sacrifice is not transactional payment but an exchange of life-essences. The verse becomes the theological core text for many later interpretations of atonement, including the New Testament’s reading of the death of Jesus.",
        "User original",
    ),
