        "Note",
        "Note",
        "<strong>The most contested verse in modern Leviticus interpretation.</strong> Hebrew: <em>v’ish asher yishkav et zakhar mishk’vei ishah</em>. Readings range across a wide field, including the traditional view that all male same-sex relations are forbidden; readings that limit the scope to particular contexts (e.g. cult prostitution, exploitation, or one specific role); and readings that focus on the rare phrase <em>mishk’vei ishah</em> (“the lyings of a woman”). The interpretive debate is genuinely live in scholarship and religious communities. The corresponding female case is not addressed here.",
        "User original",
