        "<strong>The festival that became Rosh Hashanah.</strong> The Torah names the first day of the seventh month only as <em>zikhron teru‘ah</em> (“memorial of blasts”) — there is no explicit “New Year” language, since biblical Israel reckoned the new year from spring (Nisan). The shift to a fall new year is post-biblical; Mishnah <em>Rosh Hashanah</em> 1:1 ultimately recognizes four distinct new-years for different purposes.",
