        26,
        12,
        "",
        "I will walk among you",
        "word",
        "Hebrew",
        "Hebrew",
        "<strong>V’hithallakhti b’tokhakhem (<em>וְהִתְהַלַּכְתִּי</em> <em>בְּתוֹכְכֶם</em>).</strong> The verb form <em>hithpa‘el</em> of <em>halakh</em> (“to walk”) is the same form used of God in Eden (Gen 3:8) — an iterative, easy walking-about. The covenantal blessing is framed as a return to Edenic intimacy: God resumes walking in the midst of his people as he once walked in the garden. Paul cites this verse in 2 Corinthians 6:16.",
        "User original",
